<script setup lang="ts">import { onMounted, ref } from 'vue'; import { api } from '../api'; import { enumLabel, formatDate, t } from '../i18n'; import type { AuditLog } from '../types'; const logs=ref<AuditLog[]>([]); onMounted(async()=>logs.value=await api('/api/admin/audit-logs'))</script>
<template><div class="page-title"><div><span class="eyebrow">{{ t('securityTrail') }}</span><h1>{{ t('auditTitle') }}</h1><p>{{ t('auditDescription') }}</p></div></div><article class="card table-scroll"><table><thead><tr><th>{{ t('time') }}</th><th>{{ t('actor') }}</th><th>{{ t('action') }}</th><th>{{ t('target') }}</th><th>{{ t('result') }}</th><th>{{ t('description') }}</th></tr></thead><tbody><tr v-for="item in logs" :key="item.id"><td>{{ formatDate(item.createdAt) }}</td><td>{{ item.actorUsername }}<small>{{ item.sourceIp }}</small></td><td class="mono">{{ enumLabel(item.action) }}</td><td>{{ enumLabel(item.targetType) }} {{ item.targetId || '' }}</td><td><span :class="['badge', item.result.toLowerCase()]">{{ enumLabel(item.result) }}</span></td><td>{{ item.detail }}</td></tr></tbody></table><div v-if="!logs.length" class="empty">{{ t('noAuditLogs') }}</div></article></template>
